<?php require_once __DIR__.'/paymongo.php';$borrowerAccount=borrower_user();$extension=$extension??false;portal_start($extension?'Payment extension':'Make a payment',$extension?'payment-extension':'payments');$loans=array_values(array_filter(borrower_loans($borrowerAccount['user_id']),fn($a)=>$a['status']==='active')); ?>
<section class="portal-card"><p><?= $extension?'If you cannot pay the installment principal, pay this month’s interest and carry the unpaid principal to the next installment.':'Pay the earliest unpaid installment using GCash or card. You can also choose to pay the monthly interest first.' ?></p><p>Your balance changes only after payment confirmation. Returning from checkout or cancelling does not mark a payment as paid.</p></section>
<?php if(!$loans): ?><section class="portal-card">No active loan is available for payment.</section><?php endif; foreach($loans as $a): ?><section class="portal-card"><h2>Loan UW-<?= $a['agreement_id'] ?></h2><?php $mode=$extension?'interest-only':($_GET['mode']??'regular');if(!$extension): ?><p><a href="payments.php?mode=regular">Full installment</a> · <a href="payments.php?mode=interest-only">Monthly interest only</a></p><?php endif; try{$q=pm_quote($a,$mode); ?><p>Due date: <?= e($q['due_date']) ?></p><h3>Pay now: <?= money($q['amount_cents']/100) ?></h3><?php if($mode==='interest-only'): ?><p>Principal carried forward: <strong><?= money($q['carry_cents']/100) ?></strong></p><p>Next due: <strong><?= e($q['next_due_date']) ?> — <?= money($q['next_amount_cents']/100) ?></strong></p><p><?= $q['added_interest_cents']?'This adds one month with the usual monthly interest of '.money($q['added_interest_cents']/100).' on the original principal.':'No extra interest or penalty is charged on the carried amount.' ?></p><?php endif;
$open=db("SELECT * FROM paymongo_orders WHERE agreement_id=? AND state IN ('creating','pending','uncertain','review') LIMIT 1",[$a['agreement_id']])->get_result()->fetch_assoc();if($open): ?><p>An existing checkout is awaiting confirmation. <a href="payment-history.php">Review payment status</a> before starting another.</p><?php else: $configured=true;try{$c=pm_config($a['lender_id']);if(!$c['live']&&!in_array((int)$borrowerAccount['user_id'],array_map('intval',$c['test_borrower_ids']??[]),true))throw new DomainException('Online payments are still being configured for your lender.');if(!$c['live'])echo '<p><strong>TEST MODE — simulated payments for this test borrower only.</strong></p>';}catch(DomainException $e){$configured=false;echo '<p>'.e($e->getMessage()).'</p>';}
?><form class="portal-form" method="post" action="../controllers/borrower-checkout.php"><?php csrf(); ?><input type="hidden" name="agreement_id" value="<?= $a['agreement_id'] ?>"><input type="hidden" name="mode" value="<?= e($mode) ?>"><input type="hidden" name="quote_token" value="<?= hash('sha256',json_encode($q)) ?>"><label class="check"><input type="checkbox" name="confirm" value="yes" required>I agree to pay the displayed amount<?= $mode==='interest-only'?' and accept the displayed principal carry and updated schedule':'' ?>.</label><button <?= !$configured?'disabled':'' ?>>Continue to GCash / card</button></form><?php endif;
}catch(DomainException $e){echo '<p>'.e($e->getMessage()).'</p>';} ?></section><?php endforeach; ?><section class="portal-card"><a href="payment-history.php">View payments and pending checkout sessions</a></section><?php portal_end(); ?>